function download(name,blob){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('dynora-visual-assets-4',1);r.onupgradeneeded=()=>r.result.createObjectStore('objects',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function storage(mode,fn){const d=await db();try{return await new Promise((resolve,reject)=>{const tx=d.transaction('objects',mode);let result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);fn(tx.objectStore('objects'),v=>result=v)})}finally{d.close()}}
function makeId(){return 'prop_'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,9)).replaceAll('-','')}
function cloneMaterial(material){return Array.isArray(material)?material.map(m=>m.clone()):material.clone()}
