 let config;try{config=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{config={}}config={adaptive:true,fastUI:true,targetFPS:30,preset:'balanced',exposure:1.05,environment:1,grid:false,...config};if(!GRAPHICS_PRESETS[config.preset])config.preset='balanced';
 const adaptive=new AdaptivePixels({max:Math.max(.65,Math.min(devicePixelRatio||1,1)),enabled:!!config.adaptive,target:[30,45,60].includes(config.targetFPS)?config.targetFPS:45});let performanceReport=null,pendingRatio=null,previewRect=null;
